import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Star, FileText, Search, TrendingUp } from 'lucide-react';
import './Dashboard.css';

function Dashboard() {
  const { user } = useAuth();

  const features = [
    {
      icon: <Star size={48} />,
      title: 'Famous Movies',
      description: 'Explore sentiment analysis of popular movies with detailed reviews and visualizations',
      link: '/famous-movies',
      color: '#fbbf24'
    },
    {
      icon: <FileText size={48} />,
      title: 'Custom Analysis',
      description: 'Paste any movie review and get instant sentiment analysis with advanced graphs',
      link: '/custom-analysis',
      color: '#667eea'
    },
    {
      icon: <Search size={48} />,
      title: 'Movie Search',
      description: 'Search for any movie by name and discover its sentiment based on IMDB ratings',
      link: '/movie-search',
      color: '#10b981'
    }
  ];

  return (
    <div className="dashboard-container">
      <div className="dashboard-hero">
        <h1 className="fade-in">Welcome back, {user?.username}! 🎬</h1>
        <p className="fade-in">Analyze movie reviews and discover sentiment trends with AI-powered insights</p>
      </div>

      <div className="features-grid">
        {features.map((feature, index) => (
          <Link
            key={index}
            to={feature.link}
            className="feature-card fade-in"
            style={{ animationDelay: `${index * 0.1}s` }}
          >
            <div className="feature-icon" style={{ color: feature.color }}>
              {feature.icon}
            </div>
            <h3>{feature.title}</h3>
            <p>{feature.description}</p>
            <div className="feature-arrow">→</div>
          </Link>
        ))}
      </div>

      <div className="info-section fade-in">
        <div className="info-card">
          <TrendingUp size={32} color="#667eea" />
          <h3>Advanced Analytics</h3>
          <p>
            Our sentiment analysis uses multiple AI models including VADER and TextBlob
            to provide accurate and detailed insights into movie reviews.
          </p>
        </div>
        <div className="info-card">
          <div className="sentiment-examples">
            <span className="badge badge-positive">Positive</span>
            <span className="badge badge-neutral">Neutral</span>
            <span className="badge badge-negative">Negative</span>
          </div>
          <h3>Three-Way Classification</h3>
          <p>
            Reviews are classified into positive, negative, or neutral sentiments
            with confidence scores and detailed breakdowns.
          </p>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
